examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    MonarchSaveStatusIndicator(.{{states.0|raw}}, labels: labels)
    MonarchSaveStatusIndicator(.{{states.1|raw}}, labels: labels)
    MonarchSaveStatusIndicator(.{{states.2|raw}}, savedAt: .now.addingTimeInterval(-{{savedAgoSeconds}}), labels: labels)
    MonarchSaveStatusIndicator(.{{states.3|raw}}, labels: labels, onRetry: {})
}

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    MonarchSaveStatusIndicator(.unsaved, labels: labels)
    MonarchSaveStatusIndicator(.saving, labels: labels)
    MonarchSaveStatusIndicator(.saved, savedAt: .now.addingTimeInterval(-120), labels: labels)
    MonarchSaveStatusIndicator(.error, labels: labels, onRetry: {})
}
